import sys

def main():
    import sys
    import itertools

    def read_ints():
        return list(map(int, sys.stdin.read().split()))

    data = read_ints()
    n = data[0]
    a = data[1:]

    total_sum = sum(a)
    if total_sum % 2 != 0:
        print("-1")
        return

    target_sum = total_sum // 2

    def can_partition(arr, target):
        if target == 0:
            return True
        if len(arr) == 0:
            return False
        return can_partition(arr[1:], target - arr[0]) or can_partition(arr[1:], target)

    if not can_partition(a, target_sum):
        print("-1")
        return

    def find_partition(arr, target, path):
        if target == 0:
            return path
        if len(arr) == 0:
            return None
        result = find_partition(arr[1:], target - arr[0], path + [arr[0]])
        if result is not None:
            return result
        return find_partition(arr[1:], target, path)

    partition1 = find_partition(a, target_sum, [])
    partition2 = [x for x in a if x not in partition1]

    print(" ".join(map(str, partition1 + partition2)))

if __name__ == "__main__":
    main()
